    # --- L2 (15 casos) ---
    agregar("G28-L2-01", CLASE_28, "L2", "Vibración severa en el volante al frenar entre 80 y 110 km/h; al soltar el freno el auto rueda suavemente a 100 km/h sin vibración alguna en la dirección.", "COTIDIANO", "frenado_80_110kmh", "vibracion_volante_al_frenar|suave_sin_frenar", "llantas_desbalanceadas", "", "NO", "SI", "Llantas desbalanceadas o desalineadas", "L2 vibración exclusiva al frenar descarta balanceo de ruedas.")
    agregar("G28-L2-02", CLASE_28, "L2", "El pedal de freno late con pulsaciones rítmicas al detenerse en bajadas; los discos delanteros presentan rebaba perimetral de 2 mm y surcos profundos.", "TALLER", "frenada_bajada", "pulsaciones_ritmicas_pedal|rebaba_disco_2mm|surcos", "falla_pastillas_freno", "", "NO", "SI", "Desgaste de pastillas y zapatas de freno", "L2 pulsación y rebaba severa en discos.")
    agregar("G28-L2-03", CLASE_28, "L2", "Alabeo en disco ventilado delantero tras pasar por charco de agua con frenos calientes; el reloj palpador acusa deformación térmica visible al girar la maza.", "TECNICO", "choque_termico_charco", "deformacion_termica_charco|alabeo_girar_maza", "falla_rodamiento", "", "NO", "NO", "", "L2 choque térmico por enfriamiento brusco.")
    agregar("G28-L2-04", CLASE_28, "L2", "Hola, cuando voy a 90 km/h y toco apenas el freno el timón tironea de lado a lado; si acelero a 120 km/h sin pisar freno el timón está quietecito.", "WHATSAPP", "frenado_90kmh", "timon_tironea_al_tocar_freno|quieto_a_120kmh_sin_freno", "desalineacion_ruedas", "", "NO", "SI", "Llantas desbalanceadas o desalineadas", "L2 volante tiembla solo con freno descarta alineación.")
    agregar("G28-L2-05", CLASE_28, "L2", "Medición de espesor de disco con micrómetro exterior marca 19.4 mm; el grabado mínimo del fabricante (Min TH) especifica 20.0 mm de descarte.", "TECNICO", "metrologia_disco_micrometro", "espesor_19_4mm_bajo_min_th_20mm", "falla_caliper", "", "NO", "NO", "", "L2 disco por debajo del espesor mínimo de seguridad.")
    agregar("G28-L2-06", CLASE_28, "L2", "Frenada ondulante a baja velocidad antes de llegar a cero; el auto frena por impulsos cíclicos sincronizados con el giro de la rueda delantera derecha.", "COTIDIANO", "detencion_cero", "frenada_ondulante_impulsos_ciclicos", "falla_sensor_abs", "", "NO", "SI", "Falla en sensor de velocidad de rueda ABS", "L2 variación de espesor de disco genera frenada a tirones.")
    agregar("G28-L2-07", CLASE_28, "L2", "Discos de freno con puntos duros de cementita azulada por sobrecalentamiento; la pastilla no muerde uniforme provocando trepidación en el pedal.", "TALLER", "frenada_severa", "puntos_cemento_azulada|trepidacion_pedal", "pastillas_vidriadas", "", "NO", "SI", "Desgaste de pastillas y zapatas de freno", "L2 manchas de cementita en pista de fricción.")
    agregar("G28-L2-08", CLASE_28, "L2", "Mi carro tironea el pedal del freno como si pataleara al frenar de 80 a 40 km/h en la panamericana. Si no piso el freno rueda sedita sin vibradera.", "ERROR_ORTOGRAFICO", "frenada_panamericana", "pedal_patalea_frenar_80_40|rueda_sedita_sin_freno", "llantas_desbalanceadas", "", "NO", "SI", "Llantas desbalanceadas o desalineadas", "L2 pataleo en pedal exclusivo con freno con ortografía informal.")
    agregar("G28-L2-09", CLASE_28, "L2", "Buenas maestro, le cambiaron las pastillas a mi auto y ahora vibra el volante al frenar. En el taller me dicen que los discos están pandeados y debieron rectificarlos.", "WHATSAPP", "post_cambio_sin_rectificar", "vibra_volante_frenar|discos_pandeados_sin_rectificar", "pastillas_defectuosas", "", "NO", "SI", "Desgaste de pastillas y zapatas de freno", "L2 pastilla plana sobre disco alabeado delata vibración.")
    agregar("G28-L2-10", CLASE_28, "L2", "Reloj comparador colocado en la maza delantera izquierda registra alabeo lateral de 0.12 mm (tolerancia máxima OEM 0.05 mm); maza de rueda sin descentramiento.", "TECNICO", "medicion_reloj_comparador", "alabeo_0_12mm_tolerancia_0_05mm|maza_sin_salto", "falla_maza_rodaje", "", "NO", "NO", "", "L2 alabeo de 0.12 mm en disco con maza correcta.")
    agregar("G28-L2-11", CLASE_28, "L2", "Fuerte zumbido y vibración en toda la carrocería en desaceleraciones bruscas desde 120 km/h; los discos presentan fisuras radiales diminutas en la pista.", "COTIDIANO", "desaceleracion_120kmh", "zumbido_vibracion_carroceria|fisuras_radiales_disco", "falla_amortiguadores", "", "NO", "NO", "", "L2 fisuras por fatiga térmica en disco gastado.")
    agregar("G28-L2-12", CLASE_28, "L2", "Vibración al frenar no atribuible a tren delantero; bujes de trapecio y rótulas sin holgura pero la pista del disco tiene variación de espesor de 0.03 mm.", "TALLER", "inspeccion_suspension_frenos", "bujes_rotulas_ok|variacion_espesor_disco_0_03mm", "holgura_suspension", "", "NO", "NO", "", "L2 DTV de 0.03 mm con suspensión impecable.")
    agregar("G28-L2-13", CLASE_28, "L2", "El pedal de freno tiembla bajo el pie en frenadas moderadas pero el testigo ABS permanece apagado y no hay códigos de sensor de rueda en memoria.", "COTIDIANO", "frenada_moderada", "pedal_tiembla_frenada_moderada|testigo_abs_apagado", "falla_sistema_abs", "", "NO", "SI", "Falla en sensor de velocidad de rueda ABS", "L2 temblor mecánico de disco vs falso disparo ABS.")
    agregar("G28-L2-14", CLASE_28, "L2", "Inspección de disco ventilado: aletas interiores de ventilación corroídas y partidas por óxido provocando deformación térmica asimétrica bajo carga.", "TECNICO", "inspeccion_aletas_ventiladas", "aletas_ventilacion_partidas_oxido|deformacion_termica", "falla_pastillas", "", "NO", "NO", "", "L2 rotura de aletas de ventilación internas.")
    agregar("G28-L2-15", CLASE_28, "L2", "Pulsación rítmica en el pedal que incrementa su frecuencia proporcionalmente a la velocidad del vehículo al frenar; calipers flotantes deslizan sin traba.", "TALLER", "prueba_proporcional_velocidad", "pulsacion_proporcional_velocidad|caliper_desliza_bien", "caliper_agarrotado", "", "NO", "SI", "Caliper de freno trabado o mordaza pegada (piston agarrotado)", "L2 frecuencia proporcional al giro descarta mordaza trabada.")

    # --- L3 (15 casos) ---
    agregar("G28-L3-01", CLASE_28, "L3", "Toyota Hilux ingresa por vibración violenta en el volante y pedal al descender cuestas a 80 km/h aplicando frenos. Se montó reloj comparador con base magnética en la mangueta: el disco delantero derecho acusa un salto lateral (runout) de 0.14 mm (límite OEM 0.04 mm), mientras que el descentramiento de la brida de la maza es de apenas 0.01 mm normal. El espesor del disco es de 26.8 mm (mínimo 26.0 mm), procediéndose a rectificado sobre maza.", "TECNICO", "metrologia_reloj_comparador_mangueta", "runout_0_14mm_disco|descentramiento_maza_0_01mm_ok|vibracion_80kmh_bajada", "llantas_desbalanceadas", "", "NO", "SI", "Llantas desbalanceadas o desalineadas", "L3 runout de 0.14 mm con maza en 0.01 mm descarta llantas.")
    agregar("G28-L3-02", CLASE_28, "L3", "Vehículo presenta sacudidas cíclicas en el pedal de freno en frenadas suaves de 50 a 0 km/h sin que el volante vibre. Se midió la variación de espesor del disco (DTV - Disc Thickness Variation) con micrómetro digital en 8 puntos equidistantes de la pista, registrándose espesor máximo de 22.045 mm y mínimo de 22.015 mm (delta de 0.030 mm, superando el límite de 0.012 mm). Las pastillas son nuevas y los bujes de horquilla no tienen juego.", "TECNICO", "medicion_dtv_8_puntos", "dtv_0_030mm_excesivo|espesor_variable_8puntos|sacudida_pedal_50_a_0", "holgura_bujes_horquilla", "", "NO", "NO", "", "L3 DTV de 0.030 mm en 8 puntos con micrómetro digital.")
    agregar("G28-L3-03", CLASE_28, "L3", "Conductor refiere que al frenar a más de 100 km/h el volante tiembla tanto que parece salirse. Se descartó desbalanceo rodando el auto a 120 km/h con acelerador constante donde la dirección no presenta ninguna vibración. Al aplicar apenas 15 bar de presión de frenado el timón entra en resonancia; los discos delanteros muestran zonas alternadas de pulido espejo y áreas oscuras de cementita provocadas por torque disparejo en pernos de rueda.", "TALLER", "descarte_balanceo_120kmh_crucero", "crucero_120kmh_sin_vibracion|resonancia_15bar_frenado|manchas_cementita_torque", "llantas_desbalanceadas", "", "NO", "SI", "Llantas desbalanceadas o desalineadas", "L3 crucero a 120 km/h perfecto descarta balanceo; tiembla solo a 15 bar.")
    agregar("G28-L3-04", CLASE_28, "L3", "Medición metrológica en disco de freno macizo trasero: espesor residual de 8.2 mm en la zona de pista (límite del fabricante estampado en el lomo MIN TH 9.0 mm) con labio exterior perimetral cortante de 1.8 mm de altura. El disco presenta una microfisura radial pasante de 12 mm de longitud desde el borde periférico hacia el centro originada por fatiga térmica.", "TECNICO", "inspeccion_micrometro_fisura", "espesor_8_2mm_bajo_min_9_0mm|rebaba_1_8mm|microfisura_radial_12mm", "falla_pastillas_freno", "", "NO", "SI", "Desgaste de pastillas y zapatas de freno", "L3 espesor 8.2 mm por debajo de Min TH 9.0 mm con fisura radial.")
    agregar("G28-L3-05", CLASE_28, "L3", "Hola maestro, tengo un Sentra 2019. Cuando manejo en pista lisa a 100 va suave como seda, pero piso el freno y el pedal zapatea feo y el timón vibra de lado a lado. En la llantería balancearon las 4 ruedas y alinearon pero sigue exactamente igual; me dicen que los discos se torcieron porque lavé el carro saliendo de la carretera.", "WHATSAPP", "post_lavado_caliente_sentra", "suave_a_100_sin_freno|zapateo_pedal_frenar|balanceo_alineacion_descartado", "llantas_desbalanceadas", "", "NO", "SI", "Llantas desbalanceadas o desalineadas", "L3 choque térmico en lavado post-carretera tras descartar balanceo.")
    agregar("G28-L3-06", CLASE_28, "L3", "Evaluación de vibración de frenado con acelerómetro triaxial montado en la pinza de freno: pico de aceleración de 3.2 G en eje longitudinal a frecuencia de 18 Hz (coincidente con 1x velocidad de giro de rueda a 80 km/h). Al desmontar el disco se encontró óxido acumulado de 0.08 mm entre la cara interior de la campana del disco y la superficie de apoyo de la maza de rueda.", "TECNICO", "analisis_acelerometro_oxido_maza", "aceleracion_3_2g_a_18hz|oxido_0_08mm_cara_maza|pico_frecuencia_rueda", "falla_rodamiento_rueda", "", "NO", "NO", "", "L3 óxido entre disco y maza de 0.08 mm genera runout inducido.")
    agregar("G28-L3-07", CLASE_28, "L3", "Discos delanteros ventilados ranurados y perforados presentan decoloración térmica azul en 360 grados y combado de 0.16 mm en periferia tras sesión de pista. Las pastillas de competición tienen 7 mm pero el disco perdió planitud dimensional; al aplicar frenos suaves a 60 km/h la presión hidráulica oscila entre 12 y 22 bar rítmicamente en el manómetro de prueba.", "TALLER", "oscilacion_presion_hidraulica_manometro", "alabeo_0_16mm_periferia|presion_oscila_12_a_22bar|manchas_azules", "falla_bomba_frenos", "", "NO", "SI", "Fuga hidraulica o aire en el sistema de frenos", "L3 oscilación manométrica de 12 a 22 bar por alabeo de 0.16 mm.")
    agregar("G28-L3-08", CLASE_28, "L3", "Mi camioneta tiembla horrible el volante cuando freno de golpe en la bajada de San Bartolo. En linea recta corre a 110 sin soltar el timon y no tiembla nada de nada. El mecanico puso un reloj con aguja en el disco y la aguja bailaba casi 15 lineas de milimetro.", "ERROR_ORTOGRAFICO", "bajada_san_bartolo", "tiembla_al_frenar_bajada|110_recto_sin_temblor|reloj_aguja_baila_15_lineas", "llantas_desbalanceadas", "", "NO", "SI", "Llantas desbalanceadas o desalineadas", "L3 reloj palpador confirma alabeo tras descartar tren delantero.")
    agregar("G28-L3-09", CLASE_28, "L3", "Alabeo térmico en disco ventilado izquierdo por torque desigual en tuercas de rueda: tuercas ajustadas entre 75 Nm y 160 Nm con pistola neumática sin torquímetro (especificación 110 Nm uniforme). Tras 1,500 km la brida del disco adoptó deformación elástica permanente de 0.11 mm provocando pulsación en pedal.", "TECNICO", "torque_desigual_pernos", "torque_desigual_75_a_160nm|deformacion_permanente_0_11mm|pulsacion", "falla_maza", "", "NO", "NO", "", "L3 deformación por apriete disparejo con pistola neumática.")
    agregar("G28-L3-10", CLASE_28, "L3", "Buenas tardes, tengo una Tucson 2017. Al frenar en autopista el pedal me patea el pie como si el ABS entrara pero el foco del ABS no prende en el tablero. En el taller escanearon y no hay códigos de sensor de rueda; midieron los discos con micrómetro y están ovalados con desgaste desparejo en la cara interna.", "WHATSAPP", "diagnostico_escaner_abs_ok", "pedal_patea_pie|foco_abs_apagado_sin_dtc|discos_ovalados_micrometro", "falla_sistema_abs", "", "NO", "SI", "Falla en sensor de velocidad de rueda ABS", "L3 zapateo mecánico en pedal con escáner ABS en 0 DTC.")
    agregar("G28-L3-11", CLASE_28, "L3", "Prueba de frenado a 100 km/h: desaceleración longitudinal inestable oscilando entre 0.45 G y 0.65 G sin modular el pedal. La inspección termográfica con cámara infrarroja revela bandas térmicas circunferenciales a 420°C alternadas con bandas frías a 210°C en la pista del rotor debido a contacto discontinuo de la pastilla sobre el disco deformado.", "TECNICO", "termografia_infrarroja_rotores", "desaceleracion_oscilante_0_45_0_65g|bandas_termicas_420c_210c", "falla_servofreno", "", "NO", "SI", "Falla en servofreno (booster) o linea de vacio", "L3 termografía revela gradiente térmico de 210°C por contacto discontinuo.")
    agregar("G28-L3-12", CLASE_28, "L3", "Rectificado de discos en torno paralelo: se constata espesor inicial de 21.2 mm; para eliminar el alabeo de 0.13 mm y los surcos se requiere maquinar 1.4 mm en total, lo cual dejaría el disco en 19.8 mm por debajo de la cota mínima de 20.4 mm. Se dictamina descarte y sustitución obligatoria por límite de desgaste estructural alcanzado.", "TALLER", "proceso_rectificado_torno", "salto_0_13mm_requiere_1_4mm|quedaria_19_8mm_bajo_min_20_4|descarte", "falla_pastillas", "", "NO", "NO", "", "L3 descarte técnico por cota mínima excedida en rectificado.")
    agregar("G28-L3-13", CLASE_28, "L3", "Vibración de alta frecuencia en el pedal de freno al frenar suavemente en pendientes: la medición con rugosímetro arroja rugosidad Ra de 4.8 micrómetros (especificación OEM Ra 0.8 a 1.5 um) debido a mecanizado previo defectuoso con avance de herramienta excesivo, provocando efecto de rosca sobre el forro de la pastilla.", "TECNICO", "metrologia_rugosimetro", "rugosidad_ra_4_8um_excesiva|efecto_rosca_forro|vibracion_alta_frecuencia", "falla_pastillas_freno", "", "NO", "SI", "Desgaste de pastillas y zapatas de freno", "L3 rugosidad Ra de 4.8 um por mecanizado defectuoso.")
    agregar("G28-L3-14", CLASE_28, "L3", "El cliente reclama que después de cambiar rótulas y terminales el auto sigue vibrando al frenar fuerte. Se montó comparador en el disco izquierdo registrándose 0.10 mm de alabeo en disco y 0.005 mm en maza; al rotar el disco 180 grados sobre la maza el alabeo se mantiene en 0.10 mm confirmando deformación intrínseca del rotor y no de montaje.", "TALLER", "prueba_rotacion_180_grados", "alabeo_0_10mm_persiste_rotacion_180|maza_0_005mm_ok", "falla_suspension_rotulas", "", "NO", "SI", "Llantas desbalanceadas o desalineadas", "L3 prueba de rotación a 180° confirma alabeo del disco y no de maza.")
    agregar("G28-L3-15", CLASE_28, "L3", "Rotor de freno ventilado de 320 mm presenta alabeo lateral de 0.09 mm y variación de grosor periférico de 0.022 mm. En dinamómetro de chasis la fuerza de frenado presenta ondulación senoidal de 450 N a 70 km/h con presión hidráulica constante de 25 bar en la línea principal de freno.", "TECNICO", "dinamometro_chasis_fuerza_frenado", "ondulacion_senoidal_450n|salto_0_09mm_dtv_0_022mm|presion_25bar_constante", "falla_bomba_frenos", "", "NO", "SI", "Fuga hidraulica o aire en el sistema de frenos", "L3 fuerza de frenado ondulante senoidal de 450 N en dinamómetro.")

