    agregar("G29-L1-02", CLASE_29, "L1", "Hola, cada vez que piso el pedal del freno suena como un soplido de aire adentro.", "WHATSAPP", "ralenti", "soplido_aire_al_pisar_freno", "", "", "SI", "NO", "", "L1 silbido de diafragma de booster.")
    agregar("G29-L1-03", CLASE_29, "L1", "Al pisar el freno en ralentí el motor empieza a temblar y se quiere apagar.", "COTIDIANO", "ralenti_frenado", "motor_tiembla_al_pisar_freno", "", "", "SI", "NO", "", "L1 fuga de vacío que descalibra ralentí.")
