    agregar("G29-L1-05", CLASE_29, "L1", "Pérdida de presión de vacío en el acumulador neumático del servofreno.", "TECNICO", "diagnostico", "perdida_vacio_servofreno", "", "", "SI", "NO", "", "L1 reporte técnico de depresión insuficiente.")
    agregar("G29-L1-06", CLASE_29, "L1", "Siento que el pedal está tieso desde la mañana y no cede nada al dar arranque.", "COTIDIANO", "arranque_manana", "pedal_tieso_no_cede_al_arranque", "", "", "SI", "NO", "", "L1 falla en prueba de retención de vacío.")
    agregar("G29-L1-07", CLASE_29, "L1", "Se escucha un silbido continuo debajo del tablero en la zona de los pedales.", "COTIDIANO", "marcha", "silbido_continuo_zona_pedales", "", "", "SI", "NO", "", "L1 fuga en retén o fuelle del émbolo de entrada.")
    agregar("G29-L1-08", CLASE_29, "L1", "El freno se puso como un palo de duro y el carro no se detiene rapido.", "ERROR_ORTOGRAFICO", "detencion", "freno_como_palo_duro|no_detiene_rapido", "", "", "SI", "NO", "", "L1 pedal duro con ortografía informal.")
    agregar("G29-L1-09", CLASE_29, "L1", "Buenas, pisando el freno se acelera el motor a 1500 revoluciones solo.", "WHATSAPP", "ralenti", "motor_se_acelera_al_pisar_freno", "", "", "SI", "NO", "", "L1 entrada masiva de aire no medido.")
