    agregar("G29-L2-01", CLASE_29, "L2", "Pedal de freno extremadamente rígido que exige esfuerzo físico excesivo; al apagar el motor y bombear no se siente ninguna diferencia de dureza.", "COTIDIANO", "frenado_urbano", "pedal_rigido_esfuerzo_excesivo|sin_cambio_al_bombear", "pedal_esponjoso", "", "NO", "SI", "Fuga hidraulica o aire en el sistema de frenos", "L2 pedal duro constante vs pedal esponjoso.")
    agregar("G29-L2-02", CLASE_29, "L2", "Silbido fuerte de fuga de aire en la cabina al pisar el pedal de freno en ralentí; el motor se desestabiliza con DTC P0171 por entrada de aire pirata.", "TALLER", "ralenti_frenado", "silbido_cabina_al_pisar|motor_inestable_dtc_p0171", "falla_sensor_oxigeno", "P0171", "NO", "SI", "Falla en sensor de oxigeno o mezcla rica", "L2 diafragma perforado ingresa aire falso con P0171.")
    agregar("G29-L2-03", CLASE_29, "L2", "La manguera de vacío del booster al múltiple de admisión está cuarteada y colapsada por aplastamiento térmico, anulando el vacío hacia el servofreno.", "TECNICO", "inspeccion_vano_motor", "manguera_vacio_cuarteada_colapsada|sin_vacio_booster", "falla_bomba_vacio", "", "NO", "NO", "", "L2 colapso físico de manguera de succión.")
    agregar("G29-L2-04", CLASE_29, "L2", "Hola, mi carro frena bien una sola vez, pero si tengo que frenar dos veces seguidas el pedal se pone como roca y ya no frena nada.", "WHATSAPP", "frenadas_sucesivas", "pedal_roca_segunda_frenada|no_retiene_vacio", "falla_pastillas", "", "NO", "SI", "Desgaste de pastillas y zapatas de freno", "L2 incapacidad de mantener vacío en frenadas seguidas.")
    agregar("G29-L2-05", CLASE_29, "L2", "Válvula check antirretorno del servofreno atascada en posición cerrada; no permite generar depresión en la cámara de vacío del servofreno.", "TECNICO", "prueba_valvula_check", "valvula_check_atascada_cerrada|sin_depresion_camara", "falla_cilindro_maestro", "", "NO", "NO", "", "L2 válvula antirretorno bloqueada.")
    agregar("G29-L2-06", CLASE_29, "L2", "Al pisar el freno a fondo el pedal se mantiene arriba durísimo; el nivel de líquido en el depósito está al máximo y no hay fugas en las ruedas.", "COTIDIANO", "frenado_emergencia", "pedal_arriba_durisimo|nivel_liquido_maximo_sin_fugas", "fuga_liquido", "", "NO", "SI", "Fuga hidraulica o aire en el sistema de frenos", "L2 pedal duro con nivel OK descarta fuga.")
    agregar("G29-L2-07", CLASE_29, "L2", "Motor diésel 2.5 con bomba de vacío en el alternador; la paleta interna se rompió entregando solo 5 inHg de vacío en lugar de los 20 inHg requeridos.", "TALLER", "medicion_bomba_vacio", "bomba_vacio_5inhg_baja|paleta_rota", "falla_alternador", "", "NO", "NO", "", "L2 déficit de vacío por depresor mecánico.")
    agregar("G29-L2-08", CLASE_29, "L2", "Mi auto ase pssss cada ves que piso el freno y el pedal se puso como piedra para frenar en los semaforos.", "ERROR_ORTOGRAFICO", "detencion_semaforo", "sonido_pssss_freno|pedal_como_piedra", "pedal_esponjoso", "", "NO", "SI", "Fuga hidraulica o aire en el sistema de frenos", "L2 silbido pssss con pedal rígido con ortografía informal.")
    agregar("G29-L2-09", CLASE_29, "L2", "Buenas maestro, en frío el pedal tiene buena asistencia pero al calentar el motor se endurece totalmente y el motor ratea al frenar.", "WHATSAPP", "motor_caliente", "pedal_endurece_en_caliente|motor_ratea_al_frenar", "falla_bobinas", "", "NO", "SI", "Falla en bujias o bobinas de encendido (misfire)", "L2 fuga térmica en servofreno altera mezcla en caliente.")
    agregar("G29-L2-10", CLASE_29, "L2", "Prueba de hermeticidad de servofreno: la depresión cae de 18 inHg a 0 inHg en menos de 5 segundos tras cortar el contacto del motor.", "TECNICO", "prueba_vacuometro", "depresion_cae_18_a_0inhg_5seg|fuga_interna_booster", "falla_valvula_purgado", "", "NO", "NO", "", "L2 caída abrupta de vacío en prueba de retención.")
    agregar("G29-L2-11", CLASE_29, "L2", "DTC C1246 referente a presión baja del sensor del servofreno en vehículo con start-stop; el motor no se apaga en paradas por falta de asistencia de vacío.", "TECNICO", "diagnostico_start_stop", "dtc_c1246|presion_baja_sensor_booster|start_stop_inhabilitado", "falla_bateria", "C1246", "NO", "NO", "", "L2 código C1246 por baja presión de servofreno.")
    agregar("G29-L2-12", CLASE_29, "L2", "El pedal de freno no baja al dar arranque con el pie apoyado; prueba estándar de servofreno fallida confirmando nula amplificación por vacío.", "TALLER", "prueba_arranque_pie_apoyado", "pedal_no_baja_al_arrancar|falla_prueba_servofreno", "falla_bomba_frenos", "", "NO", "SI", "Fuga hidraulica o aire en el sistema de frenos", "L2 prueba clásica de encendido con pie en pedal fallida.")
    agregar("G29-L2-13", CLASE_29, "L2", "Fuelle protector del émbolo de mando roto permitiendo ingreso de polvo y desgaste prematuro del retén de estanqueidad de la válvula de aire atmosférico.", "TECNICO", "inspeccion_fuelle_embolo", "fuelle_roto_polvo|desgaste_reten_valvula_atmosferica", "falla_cilindro_maestro", "", "NO", "NO", "", "L2 degradación de sello atmosférico en pedal.")
    agregar("G29-L2-14", CLASE_29, "L2", "Al pisar el freno en bajada pronunciada el vehículo casi no desacelera requiriendo activar el freno de mano; las pastillas y discos están nuevos.", "COTIDIANO", "frenado_emergencia_bajada", "no_desacelera_pedal_duro|pastillas_discos_nuevos", "falla_pastillas", "", "NO", "SI", "Desgaste de pastillas y zapatas de freno", "L2 componentes de fricción nuevos pero pedal tieso.")
    agregar("G29-L2-15", CLASE_29, "L2", "Presencia de aceite de motor dentro de la cámara de vacío del servofreno proveniente de la manguera de respiradero del depresor de vacío.", "TALLER", "desarme_booster", "aceite_motor_camara_booster|diafragma_degradado_aceite", "fuga_liquido_frenos", "", "NO", "SI", "Fuga hidraulica o aire en el sistema de frenos", "L2 diafragma degradado por absorción de aceite de motor.")

    # --- L3 (15 casos) ---
    agregar("G29-L3-01", CLASE_29, "L3", "En un Toyota Yaris el cliente reclama que el pedal de freno se puso durísimo y el motor ratea cada vez que frena en los cruces. Se conectó vacuómetro con conector en 'T' entre el múltiple y el booster: el múltiple genera 19 inHg estables en ralentí, pero al pisar el pedal de freno el vacío colapsa instantáneamente a 4 inHg mientras se escucha un silbido continuo por debajo del pedalier. El escáner registra STFT en +25% y DTC P0171 provocado por la entrada masiva de aire no medido a través del diafragma roto del servofreno.", "TECNICO", "diagnostico_vacuometro_en_t", "vacio_colapsa_19_a_4inhg_frenar|silbido_pedalier|stft_mas_25_dtc_p0171|diafragma_roto", "falla_sensor_maf", "P0171", "NO", "SI", "Falla en sensor de oxigeno o mezcla rica", "L3 vacuómetro en T acusa caída a 4 inHg y P0171 por diafragma roto.")
    agregar("G29-L3-02", CLASE_29, "L3", "Camioneta Nissan Navara 2.5 Diésel ingresa con pedal de frenos rígido como un bloque de cemento. Se midió la depresión generada por la bomba de vacío mecánica adosada al alternador con vacuómetro directo marcando solo 4 inHg (especificación OEM 21 a 24 inHg). Al desarmar la bomba de vacío se constató que la paleta rotativa de grafito se partió en tres pedazos bloqueando el canal de lubricación. Tras reemplazar la bomba de vacío el sistema recuperó 22 inHg y el pedal retornó a su suavidad original.", "TALLER", "medicion_depresor_navara", "depresion_4inhg_baja_vs_22inhg|paleta_grafito_rota|bomba_vacio_alternador", "falla_servofreno_vacio", "", "NO", "NO", "", "L3 rotura de paleta de grafito en depresor con 4 inHg vs 22 inHg.")
    agregar("G29-L3-03", CLASE_29, "L3", "Prueba secuencial de retención de vacío en servofreno: 1) Con motor en marcha se alcanza régimen térmico normal; 2) Se apaga el motor y se espera 15 minutos; 3) Al aplicar el pedal por primera vez se encuentra completamente rígido sin ningún recorrido de asistencia residual. Se desmontó la válvula antirretorno plástica de la manguera y al soplar por ambos lados el aire pasa libremente en ambos sentidos debido a rotura del asiento cónico interno de goma.", "TECNICO", "prueba_retencion_15min_valvula_check", "sin_asistencia_residual_15min|valvula_check_pasa_aire_ambos_lados|asiento_roto", "falla_cilindro_maestro", "", "NO", "NO", "", "L3 válvula antirretorno no retiene vacío tras 15 minutos.")
    agregar("G29-L3-04", CLASE_29, "L3", "Vehículo con motor turbo 1.4 TSI presenta pedal de freno duro exclusivamente durante aceleraciones y subidas prolongadas. El sistema utiliza una bomba de vacío eléctrica auxiliar para compensar la falta de vacío del motor en fase de sobrealimentación positiva. Con el escáner se registró código P0556 referente a rango del sensor de vacío del booster; la bomba eléctrica auxiliar no arranca debido a que el relé de accionamiento en caja de fusibles tiene los contactos quemados.", "TECNICO", "diagnostico_bomba_electrica_tsi", "dtc_p0556|bomba_electrica_no_arranca|rele_contactos_quemados|presion_turbo_positiva", "falla_turbo_valvula", "P0556", "NO", "NO", "", "L3 P0556 y relé quemado en bomba de vacío eléctrica para motor turbo.")
    agregar("G29-L3-05", CLASE_29, "L3", "Hola maestro, tengo un Kia Rio. Cuando freno en una esquina suena un zumbido de aire chhhh por los pedales y el motor empieza a temblar feo como si se fuera a apagar. El mecánico le desconectó la manguera del booster y le tapó la entrada al motor con un corcho y el motor emparejó perfecto en ralentí.", "WHATSAPP", "prueba_desconexion_booster", "silbido_chhhh_pedales|motor_tiembla_frenar|tapar_manguera_empareja_motor", "falla_cuerpo_mariposa", "", "NO", "SI", "Cuerpo de aceleracion o valvula IAC sucia", "L3 aislamiento de manguera de booster estabiliza motor descartando IAC.")
    agregar("G29-L3-06", CLASE_29, "L3", "Pérdida súbita de asistencia de frenado a velocidad crucero. Al inspeccionar la línea de vacío se encontró que la manguera rígida de poliamida rozó contra el soporte de la batería hasta perforarse con un orificio de 5 mm. El cilindro maestro no presenta fugas de líquido hidráulico, las pastillas tienen 8 mm de espesor y el circuito hidráulico se encuentra completamente purgado sin burbujas.", "TALLER", "inspeccion_linea_poliamida_perforada", "manguera_poliamida_perforada_5mm|liquido_ok_pastillas_8mm|sin_burbujas_purga", "fuga_hidraulica_frenos", "", "NO", "SI", "Fuga hidraulica o aire en el sistema de frenos", "L3 orificio de 5 mm en línea de vacío con hidráulica 100% sana.")
    agregar("G29-L3-07", CLASE_29, "L3", "DTC C1246 y C1256 en vehículo con servofreno activo y sensor de presión de vacío integrado en el booster. La lectura en línea de datos acusa presión atmosférica permanente de 101 kPa en la cámara del servofreno aún con motor a 3000 rpm. La inspección física reveló que el diafragma de goma elastomérica se despegó perimetralmente de la carcasa metálica engrapada.", "TECNICO", "linea_datos_presion_101kpa", "dtc_c1246_c1256|presion_101kpa_sin_depresion|diafragma_despegado_carcasa", "falla_modulo_abs", "C1246", "NO", "SI", "Falla en sensor de velocidad de rueda ABS", "L3 código C1246 con presión de 101 kPa por diafragma despegado.")
    agregar("G29-L3-08", CLASE_29, "L3", "Mi carro ase un soplido horrible por los pedales cuando piso el freno y se pone duro como fierro solido. El mecanico le puso la pistola de bacio y la aguja no sube nada de nada porque la bolsa de adentro del tambor negro esta rota.", "ERROR_ORTOGRAFICO", "prueba_pistola_vacio", "soplido_pedales|duro_fierro_solido|pistola_vacio_no_retiene|bolsa_rota", "falla_liquido_frenos", "", "NO", "SI", "Fuga hidraulica o aire en el sistema de frenos", "L3 pistola Mityvac no genera vacío por diafragma roto con ortografía informal.")
    agregar("G29-L3-09", CLASE_29, "L3", "Inspección de servofreno de doble diafragma en vehículo pesado: al aplicar fuerza de 40 kg sobre el pedal la presión hidráulica generada en la salida del cilindro maestro alcanza apenas 35 bar (especificación con asistencia normal 95 a 110 bar). El vacío de alimentación desde el múltiple mide 22 inHg correcto, diagnosticándose rotura del sello interno del émbolo de reacción.", "TECNICO", "banco_pruebas_presion_hidraulica", "fuerza_40kg_genera_solo_35bar_vs_100bar|vacio_22inhg_ok|sello_embolo_roto", "falla_bomba_principal", "", "NO", "SI", "Fuga hidraulica o aire en el sistema de frenos", "L3 presión de salida 35 bar vs 100 bar con vacío OK descarta bomba.")
    agregar("G29-L3-10", CLASE_29, "L3", "Buenas, en mi camioneta Ford el freno se puso duro y no frena casi nada. En el taller revisaron y la bomba de vacío mecánica que va pegada al motor se amarró y partió la faja chica que la mueve. Las 4 ruedas tienen pastillas con media vida y no hay fuga de líquido.", "WHATSAPP", "bomba_vacio_amarrada_faja_rota", "freno_duro_no_frena|bomba_vacio_amarrada|faja_rota|pastillas_media_vida_sin_fuga", "desgaste_pastillas", "", "NO", "SI", "Desgaste de pastillas y zapatas de freno", "L3 gripado de depresor mecánico con faja rota descartando pastillas.")
    agregar("G29-L3-11", CLASE_29, "L3", "Evaluación de tiempo de respuesta de asistencia neumática: tras soltar el pedal de freno el tiempo de restablecimiento de vacío en la cámara posterior tarda 4.8 segundos (especificación menor a 0.5 s) debido a colapso parcial de la válvula de aireación atmosférica con filtro de fieltro colmatado de lodo seco bajo el pedalier.", "TECNICO", "tiempo_restablecimiento_vacio", "tiempo_4_8s_vs_0_5s|filtro_fieltro_colmatado_lodo|valvula_aireacion_lenta", "falla_caliper_pegado", "", "NO", "SI", "Caliper de freno trabado o mordaza pegada (piston agarrotado)", "L3 filtro de fieltro sucio demora restablecimiento de vacío a 4.8s.")
    agregar("G29-L3-12", CLASE_29, "L3", "DTC P0555 en vehículo con motor EcoBoost; el sensor de presión del servofreno registra voltaje fijo de 0.2V indicando circuito abierto en línea de 5V de referencia. Al corregir el cableado el sensor mide 28 kPa absolutos confirmando que la asistencia mecánica de vacío está operativa y el pedal responde suavemente.", "TECNICO", "diagnostico_linea_5v_p0555", "dtc_p0555|voltaje_0_2v_referencia_abierta|presion_28kpa_operativa", "falla_booster_mecanico", "P0555", "NO", "NO", "", "L3 código P0555 por circuito eléctrico del sensor con vacío OK.")
    agregar("G29-L3-13", CLASE_29, "L3", "El cliente ingresa manifestando que para frenar el vehículo debe apoyarse contra el respaldo del asiento con toda su fuerza. Se midió carrera de pedal encontrando solo 25 mm de desplazamiento rígido sin rebote elástico. Al desmontar el booster se descubrió corrosión severa en el resorte de retorno interior y oxidación en las paredes del cilindro por ingreso de agua de lluvia por el torpedo.", "TALLER", "desarme_booster_oxido_torpedo", "fuerza_extrema_apoyo_respaldo|carrera_25mm_rigida|resorte_oxidado_agua_torpedo", "falla_bomba_frenos", "", "NO", "SI", "Fuga hidraulica o aire en el sistema de frenos", "L3 corrosión interna por ingreso de agua de torpedo.")
    agregar("G29-L3-14", CLASE_29, "L3", "Frenos endurecidos en motor diésel Common Rail tras cambio de alternador. Se verificó que el tubo de retorno de aceite de la bomba de vacío mecánica quedó estrangulado por mala posición, provocando contrapresión de lubricación que trabó las paletas rotativas del depresor impidiendo generar más de 2 inHg de vacío.", "TECNICO", "tubo_retorno_estrangulado_depresor", "tubo_retorno_aceite_estrangulado|contrapresion_traba_paletas|vacio_2inhg", "falla_alternador", "", "NO", "NO", "", "L3 estrangulamiento de retorno de aceite anula depresor a 2 inHg.")
    agregar("G29-L3-15", CLASE_29, "L3", "Prueba de esfuerzo en pedal dinamométrico: para alcanzar desaceleración de 0.6 G se requieren 680 N de fuerza sobre el pedal (especificación con servofreno operativo 180 a 220 N). La línea de vacío registra 0 inHg debido a que el eyector venturi montado en la admisión se taponó con residuos carbonosos del sistema PCV.", "TALLER", "pedal_dinamometrico_680n_fuerza", "fuerza_680n_vs_200n|desaceleracion_0_6g|eyector_venturi_taponado_pcv", "desgaste_pastillas", "", "NO", "SI", "Desgaste de pastillas y zapatas de freno", "L3 pedal dinamométrico requiere 680 N por eyector venturi taponado.")

    return casos
